14	  background: string;
15	  // Icon-only accent color — the label always stays on the theme ink color
16	  // for contrast/legibility; only the icon is tinted to match `background`'s
17	  // hue (a lower-opacity version of the same color).
18	  iconColor?: string;
19	  class?: string;
