import type { ComponentType, SVGProps } from "react";
import { Bell as BellDotIcon } from "pixelarticons/react/Bell";
import { Waves2 as SurfboardIcon } from "pixelarticons/react/Waves2";
import { Key as KeyIcon } from "pixelarticons/react/Key";
import { CastleTower as CastleTowerIcon } from "pixelarticons/react/CastleTower";

// Maps each project entry's `icon` string (from its MDX frontmatter) to the
// actual imported pixelarticons component — content collections can't hold a
// JS/component reference, only plain data. Shared by the home page's Work
// list and each project's case-study page.
export const projectIconMap: Record<
  string,
  ComponentType<SVGProps<SVGSVGElement>>
> = {
  BellDotIcon,
  SurfboardIcon,
  KeyIcon,
  CastleTowerIcon,
};
---
import ProjectLayout from "@/layouts/ProjectLayout.astro";
import { getCollection, render } from "astro:content";
import { projectIconMap } from "@/lib/projectIconMap";

// getStaticPaths tells Astro which pages to build at compile time.
// One page is generated per project.
export async function getStaticPaths() {
  const projects = await getCollection("projects");
  return projects.map((project) => ({
    // Entries are addressed by .id (the filename) rather than .slug.
    params: { slug: project.id },
    props: { project },
  }));
}

const { project } = Astro.props;
const { Content } = await render(project);
---

<ProjectLayout
  name={project.data.name}
  tagline={project.data.tagline}
  icon={projectIconMap[project.data.icon]}
  iconColor={project.data.iconColor}
  iconColorDark={project.data.iconColorDark}
  badgeColor={project.data.badgeColor}
  badgeColorDark={project.data.badgeColorDark}
  description={project.data.description}
  accentPhrase={project.data.accentPhrase}
  loomUrl={project.data.loomUrl}
  role={project.data.role}
  scope={project.data.scope}
>
  <Content />
</ProjectLayout>

