const embedSrc = loomUrl?.replace("/share/", "/embed/");

// JSX/Astro only renders a variable as a component if it starts with a
// capital letter — `icon` comes in lowercase as a prop, so it needs a
// capitalized alias before it can be used as `<Icon />` below.
const Icon = icon;
---

<BaseLayout
  title={name}
  description={tagline}
  actions={[{ label: "Back", shortcut: "esc", href: "/home" }]}
>
  {
    /* Warms up the connection to Loom's domains as soon as the page loads,
      instead of paying full DNS+TLS+redirect latency at the moment the
      reader clicks "Watch the overview". Rendered into BaseLayout's named
      "head" slot — a <link> in the default slot stays in <body> where
      it's written, it isn't auto-hoisted to <head> the way <style>/<script>
      tags are. */
  }
  {
    embedSrc && (
      <Fragment slot="head">
        <link rel="preconnect" href="https://www.loom.com" />
        <link rel="preconnect" href="https://cdn.loom.com" crossorigin />
      </Fragment>
    )
  }
  <main class="mx-auto max-w-[1120px] py-18">
    <article class="px-6 sm:px-10 lg:px-[60px]">
      <header data-animate class="mb-12 flex flex-col gap-8">
        {
          /* Breadcrumb: Home badge, then the project's own icon badge + eyebrow label
            (that project badge/label markup matches the home page's Work list rows) */
        }
        <div class="flex items-center gap-4">
          <a href="/home" class="flex items-center gap-2">
            <span
              class="bg-portfolio-muted/15 flex size-7 items-center justify-center rounded-md"
            >
              <Home width={16} height={16} className="text-portfolio-muted" />
            </span>
            <span class="text-portfolio-muted font-mono text-base underline"
              >Home</span
            >
          </a>
          <span class="text-portfolio-muted">•</span>
          <div class="flex items-center gap-2">
            <span
              class="flex size-7 shrink-0 items-center justify-center rounded-md"
              style={{
                backgroundColor: "var(--badge-color)",
                ...(badgeColor ? { "--badge-color-light": badgeColor } : {}),
                ...(badgeColorDark
                  ? { "--badge-color-dark": badgeColorDark }
                  : {}),
              }}
            >
              <Icon
                width={16}
                height={16}
                style={{
                  color: "var(--icon-color)",
                  ...(iconColor ? { "--icon-color-light": iconColor } : {}),
                  ...(iconColorDark
                    ? { "--icon-color-dark": iconColorDark }
                    : {}),
                }}
              />
            </span>
            <p
              class="text-portfolio-ink font-mono text-base tracking-[-0.18px]"
            >
              {name}
            </p>
          </div>
        </div>

        {
          /* Headline — accentPhrase (if set) renders italicized in the project's own iconColor.
            .portfolio-headline (global.css) is the shared big-title treatment
            every headline on the site uses (home page, case studies), including its fluid clamp() font-size. */
        }
        <h1 class="portfolio-headline">
          {taglineBefore}
          {
            accentIndex >= 0 && (
              <span
                class="italic"
                style={{
                  color: "var(--icon-color)",
                  ...(iconColor ? { "--icon-color-light": iconColor } : {}),
                  ...(iconColorDark
                    ? { "--icon-color-dark": iconColorDark }
                    : {}),
                }}
              >
                {accentPhrase}
              </span>
            )
          }
          {taglineAfter}
        </h1>
      </header>

      {
        /* Body — same max-width and typography as the article template's body column */
      }
      <div data-animate class="flex flex-col gap-10">
        <p class="font-plex-sans text-portfolio-ink text-2xl leading-10">
          {dek}
        </p>

        {
          (embedSrc || role || scope) && (
            <div class="flex flex-col gap-10">
              {/* Properties row: overview toggle + Role/Scope, all optional so
                a case study can omit any of them. The toggle now opens the
                shared Lightbox (rendered once below) instead of an inline
                accordion — clicking it is just another lightbox trigger,
                identified to Lightbox.astro's delegated listener the same
                way a case-study image is (see LightboxImage.astro). */}
              <div class="flex flex-wrap items-start gap-10">
                {embedSrc && (
                  <PillButton
                    id="overview-toggle"
                    icon={Play}
                    label="Watch the overview"
                    iconColor="oklch(54.6% 0.245 262.881)"
                    background="color-mix(in oklch, oklch(54.6% 0.245 262.881) 15%, transparent)"
                    data-lightbox-trigger
                    data-lightbox-type="iframe"
                    data-lightbox-src={embedSrc}
                  />
                )}

                {role && (
                  <div class="flex flex-col gap-1 font-mono text-sm tracking-[-0.14px]">
                    <p class="text-portfolio-muted">Role</p>
                    <p class="text-portfolio-ink whitespace-nowrap">{role}</p>
                  </div>
                )}

                {scope && (
                  <div class="flex min-w-[240px] flex-1 flex-col gap-1 font-mono text-sm tracking-[-0.14px]">
                    <p class="text-portfolio-muted">Scope</p>
                    <p class="text-portfolio-ink">{scope}</p>
                  </div>
                )}
              </div>
            </div>
          )
        }

        {/* Rest of the MDX body */}
        <div
          class="article-body font-plex-sans text-portfolio-ink text-base leading-8"
        >
          <slot />
        </div>
      </div>
    </article>
  </main>

  <Lightbox />
</BaseLayout>

<script>
  import { observeGridReveal } from "@/lib/animations";
  // Re-run after every client-side navigation so the "Approach" dot grid
  // animates on each case study you open, not just the first page load.
  document.addEventListener("astro:page-load", () => observeGridReveal());
</script>

<style>
  /* MDX content comes from a separately-compiled component tree (rendered via
     <Content /> in [slug].astro), so Astro's default *scoped* styles never
     attach to it — every rule here needs :global() or it silently does nothing. */
  /* Two separate spacing tokens, easy to conflate but serving different

content.content:
235	<style>
236	  /* MDX content comes from a separately-compiled component tree (rendered via
237	     <Content /> in [slug].astro), so Astro's default *scoped* styles never
238	     attach to it — every rule here needs :global() or it silently does nothing. */
239	  /* Two separate spacing tokens, easy to conflate but serving different
240	     jobs:
241	       --ping-section-gap   — vertical rhythm BETWEEN sections. Stays a
242	                               fixed 60px at every viewport width — this is
243	                               breathing room in the reading flow, not
244	                               something that should compress on mobile.
245	       --ping-card-padding   — the INSET inside a bordered/gradient card
246	                               (Problem/Approach/Solution) and the
247	                               <article> wrapper's own horizontal margin.
248	                               This one DOES scale down on narrow screens
249	                               (24px mobile / 40px tablet / 60px desktop,
250	                               matching <article>'s own
251	                               px-6 sm:px-10 lg:px-[60px]) — a flat 60px
252	                               inset squished the readable column badly on
253	                               phones. Collapsing both into one variable
254	                               previously made the inter-section gap shrink
255	                               along with the card padding, which read as
256	                               sections crowding each other on mobile. */
257	  .article-body {
258	    --ping-section-gap: 3.75rem; /* 60px, fixed at every width */
259	    --ping-card-padding: 1.5rem; /* 24px */
260	  }
261	
262	  @media (min-width: 40rem) {
263	    .article-body {
264	      --ping-card-padding: 2.5rem; /* 40px */
265	    }
266	  }
267	
268	  @media (min-width: 64rem) {
269	    .article-body {
270	      --ping-card-padding: 3.75rem; /* 60px */
271	    }
272	  }
273	
274	  /* Each top-level block in the MDX body is wrapped in its own
275	     `.ping-section`, so this gap can sit on both sides of a section as
276	     real padding (padding needs a real box on each edge — a
277	     margin-collapse-via-adjacency-selector approach only works for a flat
278	     list of siblings, and margin between siblings COLLAPSES rather than
279	     stacking, which reads as inconsistent spacing once some sections also
280	     have their own border/background — a card's edge should have a
281	     definite, non-collapsing gap around it). The first section only gets
282	     bottom padding, matching Figma's Intro frame using pb-[60px] instead
283	     of py-[60px] since there's nothing above it to pad against.
284	     Problem/Approach/Solution below add their own padding-LEFT/RIGHT only
285	     (not the `padding` shorthand) — the shorthand would overwrite this
286	     rule's padding-top/-bottom outright, since both rules have equal
287	     specificity and the later one wins on every side it touches. Setting
288	     only the two horizontal longhands here means their own left/right
289	     inset composes with (rather than replaces) this rule's vertical gap. */
290	  .article-body :global(.ping-section) {
291	    padding-top: var(--ping-section-gap);
292	    padding-bottom: var(--ping-section-gap);
293	  }
294	
295	  .article-body :global(.ping-section:first-child) {
296	    padding-top: 0;
297	  }
298	
299	  /* "The problem" gets a plain 1px stroke outline and its own left/right
300	     inset (on top of the padding-top/-bottom every section already has
301	     from the rule above) — the one section styled as a bordered card
302	     rather than a plain full-bleed block. padding-top/-bottom here
303	     re-declare --ping-section-gap (the FIXED token), not
304	     --ping-card-padding (the responsive one) — using the responsive
305	     variable for the vertical sides was the exact bug this replaced:
306	     it made this section's vertical gap shrink along with its horizontal
307	     inset on mobile, instead of staying fixed like every other section's. */
308	  .article-body :global(.ping-section--problem) {
309	    border: 1px solid var(--section-border-color);
310	    border-radius: 0.75rem; /* 12px */
311	    padding-top: var(--ping-section-gap);
312	    padding-bottom: var(--ping-section-gap);
313	    padding-left: var(--ping-card-padding);
314	    padding-right: var(--ping-card-padding);
315	    margin-top: var(--ping-card-padding);
316	    margin-bottom: var(--ping-card-padding);
317	  }
318	
319	  /* "The approach" gets the same left/right inset, matching "The problem"
320	     above — vertical padding stays on the fixed --ping-section-gap for
321	     the same reason. position: relative gives the ::after grid layer
322	     below a containing block to size itself against. Unlike "The problem",
323	     this section stays borderless/full-bleed on purpose — the border is
324	     what marks Problem as the one "card" section, and adding one here
325	     would blur that distinction. No overflow: hidden here (unlike the
326	     original version of this rule) — the ::after grid layer below is
327	     deliberately wider than this section's own box (it bleeds 40px past
328	     the left/right edges), and clipping at the section boundary would
329	     hide exactly that bleed. The page-level overflow-x-hidden on <body>
330	     (BaseLayout.astro) is what stops that bleed from ever causing a
331	     horizontal scrollbar on narrow viewports. */
332	  .article-body :global(.ping-section--approach) {
333	    position: relative;
334	    padding-top: var(--ping-section-gap);
335	    padding-bottom: var(--ping-section-gap);
336	    padding-left: var(--ping-card-padding);
337	    padding-right: var(--ping-card-padding);
338	  }
339	
340	  /* Decorative dot-grid background for "The approach". A single tiled
341	     radial-gradient draws a 1px dot every 24px using the same weak
342	     --section-border-color hairline already used for "The problem"'s
343	     outline, so it reads as part of this design system rather than a
344	     borrowed effect. (An earlier version of this used a two-axis
345	     repeating-linear-gradient line grid, matching aphera.co's reference;
346	     swapped to dots after finding a closer reference. A per-project
347	     accent-color tint was also tried and reverted — read as too loud/
348	     colorful for this background texture even at 25% strength; the
349	     neutral hairline color works better.)
350	     Deliberately ::after, not ::before: generated content always paints
351	     after an element's real children by spec, so ::after guarantees this
352	     stays behind the section's images/copy without depending on z-index
353	     stacking order against the LightboxImage markup (which has its own
354	     position: relative wrapper). The negative z-index below is
355	     belt-and-suspenders on top of that. Also inert to pointer/click
356	     interaction. Starts fully transparent — observeGridReveal()
357	     (src/lib/animations.ts) adds .grid-active via IntersectionObserver
358	     once the section scrolls into view, which is what actually plays the
359	     gridSequence fade (defined in global.css). */
360	  .article-body :global(.ping-section--approach::after) {
361	    content: "";
362	    position: absolute;
363	    /* Bleeds the grid 40px past the section's own left/right edges (top/bottom
364	       stay flush) so it reads as wider than the text column above it, similar
365	       to aphera.co's reference. This section has no overflow: hidden of its
366	       own (unlike "The problem"/"The solution") specifically so this bleed
367	       isn't clipped — the page-level overflow-x-hidden on <body>
368	       (BaseLayout.astro) is what stops it from ever causing a horizontal
369	       scrollbar on narrow viewports instead. */
370	    inset: 0 -40px;
371	    /* "1px, transparent 1px" (not "0, transparent 1px") is what makes a
372	       crisp dot instead of a soft blurred blob — the color stays solid from
373	       center out to the 1px radius, then cuts hard to transparent at that
374	       same radius. */
375	    background-image: radial-gradient(
376	      circle,
377	      var(--section-border-color) 1px,
378	      transparent 1px
379	    );
380	    background-size: 24px 24px;
381	    /* Fades the grid out near all four edges instead of cutting off hard
382	       — two gradients (one per axis) multiplied together via
383	       mask-composite: intersect, so a point only stays fully opaque where
384	       BOTH the horizontal and vertical fade are opaque (i.e. away from
385	       every edge at once). -webkit- variants are Safari's still-required
386	       prefixed equivalents (mask-composite ergo is broadly supported
387	       unprefixed now, but -webkit-mask-composite uses different keyword
388	       values, hence "source-in" there vs "intersect" above). */
389	    mask-image:
390	      linear-gradient(
391	        to right,
392	        transparent 0%,
393	        rgba(0, 0, 0, 1) 10%,
394	        rgba(0, 0, 0, 1) 90%,
395	        transparent 100%
396	      ),
397	      linear-gradient(
398	        to bottom,
399	        transparent 0%,
400	        rgba(0, 0, 0, 1) 10%,
401	        rgba(0, 0, 0, 1) 90%,
