    outline-offset: -2px;
  }
  /* Current top-level item: tinted pill, bold + full ink color. */
  .subnav-link[aria-current="true"] {
    background-color: var(--portfolio-nav-active);
    color: var(--portfolio-ink);
    font-weight: 600;
  }

  /* ─── Deep dive sub-items ───────────────────────────────────────────────── */
  .subnav-children {
    display: grid;
    grid-template-rows: 0fr;
    margin-top: -0.5rem; /* cancels the flex gap so a collapsed list adds no space */
    transition: grid-template-rows 0.3s ease-out;
  }
  .subnav-tree {
    min-height: 0;
    overflow: hidden;
    position: relative;
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
    visibility: hidden;
    transition: visibility 0.3s;
  }
  .subnav[data-active-section="deep-dive"] .subnav-children {
    grid-template-rows: 1fr;
    margin-top: 0;
  }
  .subnav[data-active-section="deep-dive"] .subnav-tree {
    visibility: visible;
  }

  /* Tree connector: one vertical rule down the left, and a short horizontal
     tick leading into each sub-item. */
  .subnav-tree::before {
    content: "";
    position: absolute;
    left: 1.1rem;
    top: 0;
    bottom: 1.25rem;
    width: 1px;
    background: var(--section-border-color);
  }
  .subnav-sublink {
    position: relative;
    padding-left: 2rem;
  }
  .subnav-sublink::before {
    content: "";
    position: absolute;
    left: 1.1rem;
    top: 50%;
    width: 0.6rem;
    height: 1px;
    background: var(--section-border-color);
  }
  /* Current sub-item: bold ink, no pill (the pill belongs to "Deep dive"). */
  .subnav-sublink[aria-current="true"] {
    background-color: transparent;
  }

  @media (prefers-reduced-motion: reduce) {
    .subnav-link,
    .subnav-children,
    .subnav-tree {
      transition: none;
    }
  }
</style>

