  // Marker attribute for the page's script, e.g. "data-subnav-mobile".
  navAttr: string;
}

const { items, navAttr } = Astro.props;
const marker = { [navAttr]: "" };
---

<nav aria-label="Sections" {...marker} class="mobile-bar lg:hidden">
  {
    items.map((item, index) => (
      <a
        href={`#${item.id}`}
        data-section-link={item.id}
        aria-current={index === 0 ? "true" : "false"}
        class="mobile-chip"
      >
        {item.label}
      </a>
    ))
  }
</nav>

<style>
  .mobile-bar {
    position: sticky;
    /* Sits just under the sticky header (h-20 = 5rem)... */
    top: 4.25rem;
    z-index: 40;
