    outline: none;
  }
  .mobile-chip:focus-visible {
    outline: 2px solid var(--portfolio-ink);
  }

  @media (prefers-reduced-motion: reduce) {
    .mobile-bar,
    .mobile-chip {
      transition: none;
    }
  }
</style>
