     the button gets a little more side padding so the label doesn't crowd. */
  @media (hover: none), (max-width: 39.99rem) {
    .action-button :global(.keycap) {
      display: none;
    }
    .action-button {
      gap: 0;
      padding: 0.5rem 0.75rem;
      font-size: 0.875rem;
    }
  }

  @media (prefers-reduced-motion: reduce) {
    .action-button {
      transition: none;
    }
    .action-button:active {
      transform: none;
    }
  }
</style>

